final class SourceCatalog {
    final Budget budget;final Map<String,Object> identity;final String snapshotId;final List<PrecomputedCandidates.Source> sources=new ArrayList<>();
    final List<Input> inputs;final List<Entry> entries;final Map<Integer,LocalDex> decoded=new HashMap<>();
    private static final class Input {final File file;final Map<String,Object> identity;Input(File file,Map<String,Object> identity){this.file=file;this.identity=identity;}}
    private static final class Entry {final int input;final String name;final Long central;final long bytes;final String sha;Entry(int input,String name,Long central,long bytes,String sha){this.input=input;this.name=name;this.central=central;this.bytes=bytes;this.sha=sha;}}
    private static final class Digest {final String sha;final long size;final byte[] prefix,data;Digest(String sha,long size,byte[] prefix,byte[] data){this.sha=sha;this.size=size;this.prefix=prefix;this.data=data;}}
    private SourceCatalog(Budget budget,List<Input> inputs,List<Entry> entries,boolean complete){this.budget=budget;this.inputs=inputs;this.entries=entries;List<Object> in=new ArrayList<>(),src=new ArrayList<>();for(Input i:inputs)in.add(i.identity);for(int i=0;i<entries.size();++i){Entry e=entries.get(i);Map<String,Object> s=map("source_index",n(i),"input_index",n(e.input),"entry",e.name,"central_index",e.central==null?null:n(e.central),"sha256",e.sha,"bytes",n(e.bytes));src.add(s);sources.add(new PrecomputedCandidates.Source(s,inputs.get(e.input).identity));}identity=map("namespace","cli-v1","scope_complete",complete,"inputs",in,"sources",src);StringBuilder material=new StringBuilder("dmg:snapshot:source-set-v1:");material.append(PrecomputedCandidates.frame("cli-v1")).append(PrecomputedCandidates.frame(complete?"complete":"incomplete")).append(PrecomputedCandidates.frame(Integer.toString(inputs.size())));for(Input i:inputs){Map<String,Object> v=i.identity;String format=str(v.get("format"));String content=(format.equals("apk")?"sha256:apk:v1:":"sha256:raw-dex:v1:")+num(v.get("bytes"))+":"+str(v.get("sha256"));material.append(PrecomputedCandidates.frame(str(v.get("slot")))).append(PrecomputedCandidates.frame(str(v.get("role")))).append(PrecomputedCandidates.frame(format.equals("apk")?"2":"1")).append(PrecomputedCandidates.frame(str(v.get("role")).equals("resource-split")?"1":"0")).append(PrecomputedCandidates.frame(content));}material.append(PrecomputedCandidates.frame(Integer.toString(sources.size())));for(PrecomputedCandidates.Source source:sources)material.append(PrecomputedCandidates.frame(source.occurrenceId));snapshotId="snapshot:v2:"+PrecomputedCandidates.hash(PrecomputedCandidates.utf8(material.toString()));}
    private static Digest digest(InputStream stream,long limit,boolean copy,Budget budget)throws IOException{
        need(limit>=0&&limit<=512L*1024*1024,"BudgetExceeded","stream limit");MessageDigest hash=PrecomputedCandidates.sha();byte[] buffer=new byte[65536],prefix=new byte[112];int prefixSize=0;long size=0;byte[] out=copy?new byte[(int)limit]:null;
        for(;;){budget.check();int got=stream.read(buffer);if(got<0)break;if(got==0)continue;need(got<=limit-size,"BudgetExceeded","source byte limit");hash.update(buffer,0,got);int take=Math.min(got,prefix.length-prefixSize);if(take>0){System.arraycopy(buffer,0,prefix,prefixSize,take);prefixSize+=take;}if(out!=null)System.arraycopy(buffer,0,out,(int)size,got);size+=got;}
        return new Digest(PrecomputedCandidates.hex(hash.digest()),size,Arrays.copyOf(prefix,prefixSize),out);
    }
    private static long u32(byte[] b,int p){need(p>=0&&p<=b.length-4,"CorruptInput","ZIP/DEX word range");return (b[p]&255L)|((b[p+1]&255L)<<8)|((b[p+2]&255L)<<16)|((b[p+3]&255L)<<24);}
    private static long u64(byte[] b,int p){long low=u32(b,p),high=u32(b,p+4);need(high<=0x7fffffffL,"BudgetExceeded","ZIP64 signed bound");return low|(high<<32);}
    private static int u16(byte[] b,int p){need(p>=0&&p<=b.length-2,"CorruptInput","ZIP halfword range");return (b[p]&255)|((b[p+1]&255)<<8);}
    private static void dexHeader(Digest d){need(d.size>=112&&d.size<=64L*1024*1024&&d.prefix.length==112,"BudgetExceeded","DEX size");byte[] b=d.prefix;need(b[0]=='d'&&b[1]=='e'&&b[2]=='x'&&b[3]=='\n'&&b[7]==0,"CorruptInput","DEX magic");String v=new String(b,4,3,java.nio.charset.StandardCharsets.US_ASCII);need(Arrays.asList("035","037","038","039","040").contains(v),"Unsupported","local DEX version");need(u32(b,32)==d.size&&u32(b,36)==112&&u32(b,40)==0x12345678L,"CorruptInput","DEX header");}
    // Bound central-directory entry allocation before constructing ZipFile.
    private static void zipPreflight(File file,Budget budget)throws IOException{
        try(RandomAccessFile f=new RandomAccessFile(file,"r")){long length=f.length();need(length>=22&&length<=256L*1024*1024,"BudgetExceeded","APK size");int tailSize=(int)Math.min(length,65557);byte[] tail=new byte[tailSize];f.seek(length-tailSize);f.readFully(tail);int end=-1;for(int i=tail.length-22;i>=0;--i){if((i&1023)==0)budget.check();if(u32(tail,i)==0x06054b50L&&i+22+u16(tail,i+20)==tail.length){end=i;break;}}need(end>=0,"CorruptInput","ZIP end record");long absolute=length-tailSize+end;need(u16(tail,end+4)==0&&u16(tail,end+6)==0,"Unsupported","split ZIP");long count=u16(tail,end+10),size=u32(tail,end+12),offset=u32(tail,end+16);need(u16(tail,end+8)==count,"CorruptInput","ZIP entry counts");
            if(count==65535||size==0xffffffffL||offset==0xffffffffL){need(absolute>=20,"CorruptInput","ZIP64 locator");byte[] locator=new byte[20];f.seek(absolute-20);f.readFully(locator);need(u32(locator,0)==0x07064b50L&&u32(locator,4)==0&&u32(locator,16)==1,"Unsupported","ZIP64 locator/disk");long at=u64(locator,8);need(at<=length-56,"CorruptInput","ZIP64 end offset");byte[] z=new byte[56];f.seek(at);f.readFully(z);need(u32(z,0)==0x06064b50L&&u64(z,4)>=44&&u32(z,16)==0&&u32(z,20)==0,"CorruptInput","ZIP64 end");count=u64(z,32);need(u64(z,24)==count,"CorruptInput","ZIP64 count");size=u64(z,40);offset=u64(z,48);}
            need(count<=100000&&size<=(16L<<20)&&offset<=absolute&&size<=absolute-offset,"BudgetExceeded","ZIP central limits");long at=offset,stop=offset+size,seen=0,nameBytes=0;byte[] record=new byte[46];while(at<stop){budget.charge(1);need(++seen<=100000&&stop-at>=46,"BudgetExceeded","ZIP central entries");f.seek(at);f.readFully(record);need(u32(record,0)==0x02014b50L,"CorruptInput","ZIP central header");nameBytes+=u16(record,28);need(nameBytes<=(8L<<20),"BudgetExceeded","ZIP names limit");long extent=46L+u16(record,28)+u16(record,30)+u16(record,32);need(extent<=stop-at,"CorruptInput","ZIP central extent");at+=extent;}need(seen==count&&at==stop,"CorruptInput","ZIP central count");}
    }
    static SourceCatalog open(List<PrecomputedCandidates.SourceInput> current,boolean complete,Budget budget){
        need(current.size()>=1&&current.size()<=64,"BudgetExceeded","source input count");List<Input> inputs=new ArrayList<>();List<Entry> sources=new ArrayList<>();Set<String> slots=new HashSet<>();long total=0,expanded=0;
        try{for(int i=0;i<current.size();++i){budget.charge(1);PrecomputedCandidates.SourceInput spec=current.get(i);need(spec!=null&&spec.slot.length()>0&&spec.slot.length()<=32767&&spec.slot.indexOf('\0')<0&&slots.add(spec.slot),"InvalidPackage","logical slot");need(Arrays.asList("base","code-split","resource-split").contains(spec.role)&&(i==0?spec.role.equals("base"):!spec.role.equals("base")),"InvalidPackage","source role/order");File file=spec.file.getCanonicalFile();Digest raw;try(InputStream in=new FileInputStream(file)){raw=digest(in,256L<<20,false,budget);}total+=raw.size;need(total<=512L<<20,"BudgetExceeded","total input bytes");boolean magic=raw.prefix.length>=4&&raw.prefix[0]=='d'&&raw.prefix[1]=='e'&&raw.prefix[2]=='x'&&raw.prefix[3]=='\n';String kind=spec.format==null?(magic?"raw":"apk"):spec.format;need(kind.equals("raw")||kind.equals("apk"),"Unsupported","input format");inputs.add(new Input(file,map("slot",spec.slot,"role",spec.role,"format",kind,"sha256",raw.sha,"bytes",n(raw.size))));
                if(kind.equals("raw")){dexHeader(raw);expanded+=raw.size;sources.add(new Entry(i,null,null,raw.size,raw.sha));}
                else{zipPreflight(file,budget);try(ZipFile zip=new ZipFile(file,Charset.forName("IBM437"))){List<ZipEntry> ordered=new ArrayList<>();Map<String,Long> indices=new HashMap<>();Set<String> names=new HashSet<>();Enumeration<? extends ZipEntry> all=zip.entries();long central=0;while(all.hasMoreElements()){budget.charge(1);ZipEntry e=all.nextElement();need(central<100000&&names.add(e.getName()),"InvalidPackage","duplicate/too many ZIP names");if(e.getName().matches("classes(?:[2-9]|[1-9][0-9]+)?\\.dex")){need(e.getMethod()==0||e.getMethod()==8,"Unsupported","DEX compression");need(e.getSize()>=0&&e.getSize()<=64L*1024*1024,"BudgetExceeded","DEX entry size");need(ordered.size()<1024-sources.size(),"BudgetExceeded","DEX occurrence count");order(e.getName());ordered.add(e);indices.put(e.getName(),central);}else need(!e.getName().matches("classes[^/]*\\.dex"),"InvalidPackage","noncanonical DEX entry");central++;}
                    ordered.sort((a,b)->{budget.charge(1);return Long.compare(order(a.getName()),order(b.getName()));});need(!ordered.isEmpty()||spec.role.equals("resource-split"),"InvalidPackage","APK has no DEX");for(ZipEntry e:ordered){budget.check();Digest d=entry(zip,e,false,budget);dexHeader(d);expanded+=d.size;need(expanded<=512L<<20,"BudgetExceeded","expanded DEX bytes");sources.add(new Entry(i,e.getName(),indices.get(e.getName()),d.size,d.sha));need(sources.size()<=1024,"BudgetExceeded","DEX occurrence count");}}
                }need(expanded<=512L<<20&&sources.size()<=1024,"BudgetExceeded","expanded source limits");}
        }catch(IOException|IllegalArgumentException e){throw new PrecomputedCandidates.Failure("SourceMismatch","current sources cannot be read as the supported format");}
        return new SourceCatalog(budget,inputs,sources,complete);
    }
    private static long order(String name){if(name.equals("classes.dex"))return 1;long n=0;for(int i=7;i<name.length()-4;i++){int digit=name.charAt(i)-'0';need(digit>=0&&digit<=9&&n<=(0xffffffffL-digit)/10,"Unsupported","DEX name ordinal exceeds uint32");n=n*10+digit;}return n;}
    private static Digest entry(ZipFile zip,ZipEntry e,boolean copy,Budget budget)throws IOException{CRC32 crc=new CRC32();try(InputStream raw=zip.getInputStream(e);CheckedInputStream in=new CheckedInputStream(raw,crc)){Digest d=digest(in,e.getSize(),copy,budget);need(d.size==e.getSize()&&crc.getValue()==e.getCrc(),"CorruptInput","DEX entry length/CRC");return d;}}
    LocalDex dex(int index){need(index>=0&&index<entries.size(),"EvidenceMismatch","evidence source");LocalDex cached=decoded.get(index);if(cached!=null)return cached;Entry source=entries.get(index);Input input=inputs.get(source.input);budget.retain(source.bytes);try{Digest d;if(source.name==null){try(InputStream in=new FileInputStream(input.file)){d=digest(in,source.bytes,true,budget);}}else{zipPreflight(input.file,budget);try(ZipFile zip=new ZipFile(input.file,Charset.forName("IBM437"))){ZipEntry e=zip.getEntry(source.name);need(e!=null&&e.getSize()==source.bytes,"SourceMismatch","DEX entry changed");d=entry(zip,e,true,budget);}}equal(d.sha,source.sha,"SourceMismatch","materialized DEX digest");need(d.size==source.bytes,"SourceMismatch","materialized DEX length");LocalDex result=new LocalDex(d.data,budget);decoded.put(index,result);return result;}catch(IOException e){throw new PrecomputedCandidates.Failure("SourceMismatch","materialized DEX unavailable");}}
    void recheckInputs(){try{for(Input input:inputs){budget.check();Digest d;try(InputStream in=new FileInputStream(input.file)){d=digest(in,256L<<20,false,budget);}equal(d.sha,input.identity.get("sha256"),"SourceMismatch","input changed during verification");equal(n(d.size),input.identity.get("bytes"),"SourceMismatch","input length changed");}}catch(IOException e){throw new PrecomputedCandidates.Failure("SourceMismatch","source recheck failed");}}
}
